  (1099215, 138, 5732, 'lokasi d araya.. harga termasuk mahal si, mgkn krn lokasi d araya. layanan b aja makanan b sii.. kmrn pesan steak, rasa standart', 4, NULL, 'lokasi d araya.. harga termasuk mahal si, mgkn krn lokasi d araya. layanan b aja makanan b sii.. kmrn pesan steak, rasa standart', 1),
  (1099216, 202, 59493, 'Untuk lokasi bagus dibuat nongkrong, tapi untuk lokasi sendikit kotor, wifi juga bermasalahJenis mak… Lainnya', 4, NULL, 'Untuk lokasi bagus dibuat nongkrong, tapi untuk lokasi sendikit kotor, wifi juga bermasalahJenis mak… Lainnya', 1),
  (1099217, 158, 14394, 'Pelayanan salah satu servernya Sangat buruk', 1, NULL, 'Pelayanan salah satu servernya Sangat buruk', 1),
  (1099218, 203, 21214, 'Minuman yang saya pesan enak, untuk makanan kebetulan tidak pesan. Design interior nya unik sayang kapasitas terbatas, dan kurang bersih, banyak yang berdebu, asbak juga masih kotor, kamar mandi kotor. Menurut saya dengan harga segitu masih banyak tempat lain yang lebih nyaman karena kebersihannya. Lainnya', 3, NULL, 'Minuman yang saya pesan enak, untuk makanan kebetulan tidak pesan. Design interior nya unik sayang kapasitas terbatas, dan kurang bersih, banyak yang berdebu, asbak juga masih kotor, kamar mandi kotor. Menurut saya dengan harga segitu masih banyak tempat lain yang lebih nyaman karena kebersihannya. Lainnya', 1),
  (1099219, 320, 70988, 'Pelayan ramah, tempat rapi, menu lengkap', 5, NULL, 'Pelayan ramah, tempat rapi, menu lengkap', 1),
